import AppKit
import UniformTypeIdentifiers

enum ClipContent {
    case image(Data)
    case text(String)
    case link(String)
}

enum ClipboardReader {
    /// Markers apps use to say "do not keep this" (see nspasteboard.org).
    private static let doNotKeep: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]
    private static let gifType = NSPasteboard.PasteboardType("com.compuserve.gif")

    static func isSingleURL(_ string: String) -> Bool {
        guard !string.contains(where: { $0.isWhitespace }), let url = URL(string: string),
              let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https"
        else { return false }
        return url.host?.isEmpty == false
    }

    /// Reads only the kinds the user allowed. The whole read is discarded if the clipboard changes while it
    /// is being inspected, so a privacy decision is never applied to a different copy.
    static func read(_ pasteboard: NSPasteboard, images: Bool, links: Bool, text: Bool) -> ClipContent? {
        let count = pasteboard.changeCount
        let content = readUnchecked(pasteboard, images: images, links: links, text: text)
        return pasteboard.changeCount == count ? content : nil
    }

    private static func readUnchecked(_ pasteboard: NSPasteboard, images: Bool, links: Bool, text: Bool) -> ClipContent? {
        let types = pasteboard.types ?? []
        if types.contains(where: { doNotKeep.contains($0.rawValue) }) { return nil }

        let hasImage = types.contains(.png) || types.contains(.tiff) || types.contains(gifType)
        let hasString = types.contains(.string)
        let hasRichText = types.contains(.rtf) || types.contains(.rtfd)

        if types.contains(.fileURL) {
            // A single image file copied in Finder counts as a copied image; other files are ignored.
            guard images,
                  let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
                  urls.count == 1, let url = urls.first,
                  UTType(filenameExtension: url.pathExtension)?.conforms(to: .image) == true,
                  let size = try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize, size < 40_000_000,
                  let data = try? Data(contentsOf: url)
            else { return nil }
            return .image(data)
        }

        // Word processors and spreadsheets add a picture of the selection next to the text; prefer the text there.
        if hasImage, !hasRichText {
            var caption = ""
            if hasString, links || text {
                caption = pasteboard.string(forType: .string)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            }
            if caption.isEmpty || isSingleURL(caption) {
                guard images,
                      let data = pasteboard.data(forType: gifType) ?? pasteboard.data(forType: .png)
                        ?? pasteboard.data(forType: .tiff)
                else { return nil }
                return .image(data)
            }
        }

        // An explicit URL on the clipboard is a link without having to look at any text.
        if links, types.contains(.URL), let string = pasteboard.string(forType: .URL), isSingleURL(string) {
            return .link(string)
        }

        // With only "Copied links" on, the plain text still has to be looked at to tell whether it is a
        // link. It is checked in memory and dropped immediately when it is not one.
        guard hasString, links || text, let raw = pasteboard.string(forType: .string) else { return nil }
        let string = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !string.isEmpty, string.utf8.count <= 500_000 else { return nil }
        if isSingleURL(string) { return links ? .link(string) : nil }
        return text && string.count >= 2 ? .text(string) : nil
    }
}

/// Watches the general pasteboard. Does nothing unless a clipboard source is enabled and capture is not paused.
@MainActor
final class ClipboardMonitor {
    private let pasteboard: NSPasteboard
    private let library: LibraryStore
    private let settings: CaptureSettings
    private var lastChangeCount: Int
    private var timer: Timer?

    /// Apps that were frontmost since the previous check. A copy made just before switching apps is seen
    /// after the switch, so every one of these has to be allowed, not only the app in front now.
    private var recentApps: [NSRunningApplication] = []

    /// Change count of a write Kept made itself (snips, "Copy"), so it is not captured twice.
    var ownChangeCount = -1

    init(library: LibraryStore, settings: CaptureSettings, pasteboard: NSPasteboard = .general) {
        self.library = library
        self.settings = settings
        self.pasteboard = pasteboard
        lastChangeCount = pasteboard.changeCount
    }

    func start() {
        if let front = NSWorkspace.shared.frontmostApplication { recentApps = [front] }
        NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didActivateApplicationNotification, object: nil, queue: .main
        ) { [weak self] note in
            let app = note.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication
            MainActor.assumeIsolated {
                if let app { self?.recentApps.append(app) }
            }
        }
        let timer = Timer(timeInterval: 0.3, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.tick() }
        }
        timer.tolerance = 0.08
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func markOwnWrite() {
        ownChangeCount = pasteboard.changeCount
    }

    private func tick() {
        // Everything that was in front during this interval; afterwards only the current app carries over.
        let candidates = recentApps
        if let last = recentApps.last { recentApps = [last] }
        processChanges(from: candidates)
    }

    func processChanges(from candidates: [NSRunningApplication]) {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard count != ownChangeCount, !settings.paused, settings.anyClipboardCapture else { return }

        // If the source cannot be established, or any candidate is excluded, the copy is not saved.
        guard !candidates.isEmpty else { return }
        for app in candidates {
            guard let bundleID = app.bundleIdentifier else { return }
            if bundleID == Bundle.main.bundleIdentifier || settings.isExcluded(bundleID) { return }
        }
        guard let content = ClipboardReader.read(
            pasteboard, images: settings.captureImages, links: settings.captureLinks, text: settings.captureText)
        else { return }
        // The copy most likely came from the app that was in front first.
        library.ingest(content, method: .clipboard, source: candidates.first)
    }
}
